  });

  it.each(['', 'invalid'])('uses 1440 for end-of-day, ignoring disabled end value %j', (endTime) => {
    expect(parseTimeInput({ ...valid, startTime: '23:00', endTime, endOfDay: true })).toEqual({
      ok: true, times: { now: 540, start: 1380, end: 1440 },
