    expect(parseTimeInput({ ...valid, nowTime: '00:00', startTime: '00:01', endTime: '00:02' })).toEqual({
      ok: true, times: { now: 0, start: 1, end: 2 },
    });
  });

  it('reads a frozen input without changing it', () => {
    const input = Object.freeze({ ...valid });
