+
+export async function requestExplanation(
+  input: unknown,
+  adapter: ExplanationAdapter,
+  signal: AbortSignal,
+  timeoutMs = 800
+): Promise<ExplanationResult | null> {
+  if (!isValidInput(input) || signal.aborted) return null;
